import { writeFileSync } from 'node:fs'
import { tokenNames, themes } from './tokens.ts'
import type { Theme } from './tokens.ts'

function block(selector: string, theme: Theme): string {
  const lines = tokenNames.map((name) => `  --app-${name}: ${theme[name]};`)
  return `${selector} {\n${lines.join('\n')}\n}\n`
}

/** Light tokens in :root, dark tokens in .dark (the class the colour mode module sets). */
export function generateTokensCss(source: typeof themes): string {
  return [
    '/* Generated by packages/ui/src/generate-css.ts from tokens.ts. Do not edit. */',
    '',
    block(':root', source.light),
    block('.dark', source.dark),
  ].join('\n')
}

if (import.meta.main) {
  writeFileSync(new URL('../tokens.css', import.meta.url), generateTokensCss(themes))
}
